<?php require_once __DIR__.'/includes/bootstrap.php';$error='';if(is_post()){verify_csrf();public_form_guard($db, 'signup', $_POST['recaptcha_token'] ?? '');$name=trim($_POST['full_name']??'');$email=trim($_POST['email']??'');$pass=$_POST['password']??'';if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL))$error='Please enter valid account details.';elseif(!password_is_strong($pass))$error='Password must be at least 10 characters and include uppercase, lowercase and a number.';elseif($db){try{$st=$db->prepare('INSERT INTO users(email,password_hash,full_name,role) VALUES(?,?,?,"client")');$st->execute([$email,password_hash($pass,PASSWORD_DEFAULT),$name]);redirect('login.php');}catch(Throwable $e){$error='That email may already be registered.';}}}?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Create Account — WDH</title><link rel="stylesheet" href="assets/css/style.css?v=wdh-ui-v8"><link rel="stylesheet" href="assets/css/catalog.css?v=wdh-ui-v8"></head><body><?php require __DIR__.'/includes/header.php';?><main class="auth-page"><form class="auth-card" method="post"><h1>Create Your Account</h1><p>Manage domains, hosting, invoices and services from one portal.</p><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><?=csrf_field()?><input type="text" name="website" value="" class="hp-field" tabindex="-1" autocomplete="off" aria-hidden="true"><?=recaptcha_field('signup')?><label>Full Name<input name="full_name" required></label><label>Email<input type="email" name="email" required></label><label>Password<input type="password" name="password" minlength="10" required></label><button class="btn primary">Create Account</button><p>Already registered? <a href="login.php">Login</a></p></form></main><?php require __DIR__.'/includes/footer.php';?></body></html>
